struct timex tx;

// Set modes: ADJ_FREQUENCY requires privileges
tx.modes = ADJ_FREQUENCY | ADJ_STATUS;
// Example freq setting: +0.5 PPM (0.5 * 2^16)
tx.freq = 32768; 
tx.status = STA_PLL; // Enable Phase Locked Loop

clockid_t clk = CLOCK_REALTIME;

// Adjusts the clock using specified modes
int ret = clock_adjtime(clk, &tx);

// EPERM if CAP_SYS_TIME is missing
// EINVAL if parameters are out of range or clk is invalid
